import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {any} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);

  lines.push(`Customer: ${invoice.customerId}`);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);
    let lineStr = `${line.qty} x ${line.name} @ ${unitPriceStr} = ${totalStr}`;

    const discount = lineDiscount(line);
    if (discount > 0) {
      const discountPercent = line.discountPercent ?? 0;
      const discountStr = formatEuros(discount);
      lineStr += ` (${discountPercent}% discount: -${discountStr})`;
    }

    lines.push(lineStr);
  }

  const totals = invoiceTotals(invoice);

  if (totals.discount > 0) {
    const subtotalStr = formatEuros(totals.subtotal);
    const discountStr = formatEuros(totals.discount);
    const totalStr = formatEuros(totals.total);
    lines.push(`Subtotal: ${subtotalStr}`);
    lines.push(`Discount: -${discountStr}`);
    lines.push(`Total: ${totalStr}`);
  } else {
    const totalStr = formatEuros(totals.total);
    lines.push(`Total: ${totalStr}`);
  }

  return lines.join('\n');
}

