test('lineTotal calculates qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal returns whole cents', () => {
  const line = { qty: 3, unitPrice: 333 };
  const total = lineTotal(line);
  assert.equal(total, 999);
  assert.equal(total % 1, 0);
});

test('invoiceTotals returns correct subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000 + 120000,
    total: 95000 + 120000,
  });
});

test('invoiceTotals with single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'SUPPORT-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 7250);
  assert.equal(totals.total, 5 * 7250);
});

test('invoiceTotals with many lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'COPY-HOUR', qty: 5 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  }).value;

  const expected = 10 * 9500 + 5 * 6000 + 3 * 7250 + 20 * 980;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns whole cents', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'PHOTO-LIC', qty: 3 },
      { sku: 'FONT-LIC', qty: 2 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal % 1, 0);
  assert.equal(totals.total % 1, 0);
