  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };

  assert.deepEqual(removeLine(nonDraftInvoice, 'LOGO-PACK'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);

  const issued = result.value;
  assert.equal(issued.number, 'INV-2024-0001');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.customerId, invoice.customerId);
  assert.equal(issued.issueDate, invoice.issueDate);
});

test('issueInvoice assigns next number when some already exist', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2024-0001', 'INV-2024-0002'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice assigns number by year of issue date', () => {
  const invoice2023 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2023-0005', 'INV-2024-0001'];

  const result2023 = issueInvoice(invoice2023, existing);
  assert.equal(result2023.value.number, 'INV-2023-0006');

  const result2024 = issueInvoice(invoice2024, existing);
  assert.equal(result2024.value.number, 'INV-2024-0002');
});

test('issueInvoice does not mutate the original invoice', () => {
