    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalJSON = JSON.stringify(invoice);
  issueInvoice(invoice, []);
  assert.equal(JSON.stringify(invoice), originalJSON);
});

