    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(5% discount: -€24.00)'));
  assert.ok(!lines[3].includes('discount'));
  assert.ok(lines[4].includes('(15% discount: -€3.90)'));
  assert.ok(lines.some((line) => line.startsWith('Subtotal:')));
  assert.ok(lines.some((line) => line.startsWith('Discount:')));
});
